INSERT INTO traits (trait_type_name, trait_name, trait_info, trait_unit, trait_type, trait_label, column_number, allowed_values_min, allowed_values_max) VALUES
('Blossoming', 'flowering_cues', 'A plants'' flowering response to unpredictable, irregular environmental cues.', NULL, 'cat.', 'Environmental flowering cues', '1', NULL, NULL),
('Blossoming', 'flowering_time', 'Months during which taxon has open (anthetic) flowers.', NULL, 'date', 'Flowering time, by month', '2', NULL, NULL),
('Descriptive', 'flower_colour', 'The dominant flower colour, where the entire flower, the petals, or the sepals may be responsible for the observed colour.', NULL, 'cat.', 'Flower colour', '3', NULL, NULL),
('Descriptive', 'fruit_colour', 'Human visible dominant colour of a fresh fruit''s exocarp (outermost layer) at maturity.', NULL, 'cat.', 'fruit colour', '4', NULL, NULL),
('Descriptive', 'leaf_type', 'Variable distinguishing between general leaf form (shape) categories.', NULL, 'cat.', 'Leaf type', '5', NULL, NULL),
('Descriptive', 'parasitic', 'Trait indicating whether a plant forms haustoria and obtains part or all of its energy-rich carbon compounds (photosynthetic sugars), mineral nutrition and/or water directly from another plant (its host) in an interaction that does not benefit the host plant.', NULL, 'cat.', 'Plant parasitism status', '6', NULL, NULL),
('Descriptive', 'plant_climbing_mechanism', 'Mechanisms plants use to climb, including both specialised leaf and stem adaptations and stem growth habits.', NULL, 'cat.', 'Plant climbing mechanisms', '7', NULL, NULL),
('Descriptive', 'plant_growth_form', 'The form of a plant, capturing a general sense of plant height and shape, which parts of a plant are woody versus herbaceous, the number of stems arising at ground level, and the distribution of leaves relative to the main stem.', NULL, 'cat.', 'Plant growth form', '8', NULL, NULL),
('Descriptive', 'plant_growth_substrate', 'Trait broadly indicating where a plant is usually found, referencing the habitat in which a plant grows, the substrate to which a plant is attached, or a plant''s growth medium.', NULL, 'cat.', 'Plant growth substrate, eg epiphyte', '9', NULL, NULL),
('Descriptive', 'plant_height', 'Maximum vertical height of the vegetative shoot system for a taxon in a given location.', 'm', 'num', 'Plant vegetative height', '10', '0.001', '130.0'),
('Descriptive', 'plant_physical_defence_structures', 'The presence (or explicit absence) of specific physical defence structures on a plant, including spines, thorns, prickles, and sharp-tipped leaves.', NULL, 'cat.', 'physical defence structures', '11', NULL, NULL),
('Life history', 'life_history', 'Categorical description of the duration of a plant''s lifespan, from germination to death.', NULL, 'cat.', 'Life span description', '12', NULL, NULL),
('Life history', 'lifespan', 'Plant lifespan, the duration from germination to death. Lifespan refers to the death of both aboveground and belowground biomass, indicating the death of the genetic individual.', 'a', 'num', 'Lifespan years', '13', '0.1', '10000.0'),
('Fire recovery', 'fire_time_from_fire_to_50_percent_flowering', 'The time interval from a fire until 50% of the individuals in a population produce flowers.', 'mo', 'num', 'Time from fire until 50% of individuals are flowering', '14', '1.0', '500.0'),
('Fire recovery', 'fire_time_from_fire_to_50_percent_fruiting', 'The time interval from a fire until 50% of the individuals in a population produce mature fruit.', 'mo', 'num', 'Time from fire until 50% of individuals are fruiting', '15', '1.0', '500.0'),
('Fire recovery', 'fire_time_from_fire_to_flowering', 'The time interval from a fire until the first individual in a population begins flowering.', 'mo', 'num', 'Time from fire to first flowering', '16', '1.0', '1000.0'),
('Fire recovery', 'fire_time_from_fire_to_flowering_decline', 'The time interval from a fire until the degree of flowering by individuals in a population begin to decline.', 'mo', 'num', 'Time from fire until flowering declines', '17', '1.0', '1000.0'),
('Fire recovery', 'fire_time_from_fire_to_fruiting', 'The time interval from a fire until the first individual in a population produces a mature fruit with viable propagules.', 'mo', 'num', 'Time from fire to fruiting', '18', '1.0', '500.0'),
('Fire recovery', 'fire_time_from_fire_to_peak_flowering', 'The time interval from a fire until the individuals in a population display maximum flowering.', 'mo', 'num', 'Time from fire to peak flowering', '19', '1.0', '1000.0'),
('Fire response', 'life_history_ephemeral_class', 'For taxa that display an ephemeral life history, the environmental conditions associated with seed germination and seedling establishment.', NULL, 'cat.', 'Ephemeral life history class - establishment needs', '20', NULL, NULL),
('Fire response', 'plant_tolerance_fire', 'Classification scheme of plant fire tolerance, indicating morphological characteristics plants use to survive fire.', NULL, 'cat.', 'Plant fire tolerance strategy', '21', NULL, NULL),
('Fire response', 'post_fire_flowering', 'Indication of whether the magnitude of flowers produced by a taxon increases, decreases or remains unchanged following a fire.', NULL, 'cat.', 'Post-fire flowering change', '22', NULL, NULL),
('Fire response', 'post_fire_recruitment', 'A trait indicating the magnitude of seed germination and seedling establishment following a fire.', NULL, 'cat.', 'Post-fire seedling change', '23', NULL, NULL),
('Fire response', 'resprouting_capacity', 'Trait indicating whether mature individuals of a taxon are killed, resprout, or have a mixed survival response when exposed to fire that causes 100% leaf scorch.  Species where at least 70% of plants resprout are designated `resprouters`, while those where fewer than 30% of plants resprout are designated as `fire killed`. Species with an intermediate response have a mixed fire response, and are coded as `fire_killed resprouts`.', NULL, 'cat.', 'Post-fire resprouting capacity', '24', NULL, NULL),
('Fire response', 'resprouting_capacity_juvenile', 'Trait indicating whether juvenile phase individuals of a taxon are killed, resprout, or have a mixed survival response when exposed to a fire with 100% leaf scorch.', NULL, 'cat.', 'Post-fire resprouting capacity of juvenile plants', '25', NULL, NULL),
('Fire response', 'resprouting_capacity_proportion_individuals', 'Proportion of mature individuals in a population that survive a fire and resprout following a fire.', NULL, 'num', 'Post-fire proportion resprouting individuals', '26', '0.0', '1.0'),
('Fire response', 'resprouting_capacity_time_from_germination', 'A fire response trait which is the time from seed germination until individuals are able to survive and resprout following a fire where 100% of the leaves in the canopy are scorched.', NULL, 'num', 'Time from seedling germination until individuals survive a fire', '27', '0.1', '100.0'),
('Germination', 'establishment_light_environment_index', 'The minimum light environment required by seedlings for establishment, scaled from 0 to 8.', '{dimensionless}', 'num', 'Canopy light environment required for seedling establishment', '28', '0.0', '8.0'),
('Germination', 'recruitment_time', 'The months during which seed germination and seedling establishment occurs.', NULL, NULL, 'Seedling recruitment time, by month', '29', NULL, NULL),
('Germination', 'reproductive_light_environment_index', 'The minimum light environment required by plants for reproduction, scaled from 0 to 8.', '{dimensionless}', 'num', 'Canopy light environment required for reproduction', '30', '0.0', '8.0'),
('Germination', 'root_structure', 'Specific specialized types of root structures and root symbioses, especially symbioses with mycorrhizal fungi.', NULL, 'cat.', 'Plant root structures', '31', NULL, NULL),
('Germination', 'seed_germination', 'Proportion of mature seeds in a sample that germinated under specified environmental or experimental conditions.', '{count}/{count}', 'num', 'Seed germination proportion', '32', '0.0', '1.0'),
('Germination', 'seed_germination_time', 'The time interval from when a seed is exposed to suitable conditions for germinating until it germinates.', NULL, 'num', 'seed germination time', '33', '0.0', '1000.0'),
('Germination', 'seedling_establishment_conditions', 'The environmental conditions under which a taxon''s seedlings can establish, with trait values reflecting successional changes to the vegetation community.', NULL, 'cat.', 'Seedling establishment conditions', '34', NULL, NULL),
('Germination', 'seedling_germination_location', 'Binary variable distinguishing between seedlings that germinate above versus below ground.', NULL, 'cat.', 'Germination above/ below ground', '35', NULL, NULL),
('Pollination', 'pollination_syndrome', 'For a given taxon, the biotic vectors (including explicit taxa) or abiotic mechanisms that are most likely to pollinate its flowers, based on the taxon''s flower morphology.', NULL, 'cat.', 'Pollination syndrome', '36', NULL, NULL),
('Pollination', 'pollination_system', 'For a given taxon, the biotic vectors (including explicit taxa) or abiotic mechanisms that are most likely to pollinate its flowers, based on explicit field studies of pollination in the taxon''s native range (preferred) or else a combination of possible pollinators observed visiting a taxon''s flowers and the taxon''s flower morphology.', NULL, 'cat.', 'Pollination system', '37', NULL, NULL),
('Propagation', 'seed_dormancy_class', 'Mechanisms that inhibit mature seeds from germinating and the environmental or experimental cues that allow a seed to break dormancy and germinate.', NULL, 'cat.', 'Dormancy type', '38', NULL, NULL),
('Propagation', 'seed_germination_treatment', 'The treatments may be only loosely connected to the cues required for a species'' to break dormancy.', NULL, 'cat.', 'germination treatments needed', '39', NULL, NULL),
('Seedbank', 'seedbank_location', 'Location of a plant''s seedbank, the location where mature seeds are stored and viable until germinating.', NULL, 'cat.', 'Seedbank storage location', '40', NULL, NULL),
('Seedbank', 'seedbank_longevity', 'The half-life of the seedbank, which is the length of time (duration) from when seeds in a seedbank mature until more than half the seeds in a seedbank are no longer able to germinate.', NULL, 'num', 'Seedbank longevity half life', '41', '0.01', '1000.0'),
('Seedbank', 'seedbank_longevity_class', 'Categorical groupings indicating the length of time (duration) a mature seed remains in the seedbank, viable and able to germinate.', NULL, 'cat.', 'Seedbank longevity class', '42', NULL, NULL),
('Seeds', 'dispersal_unit', 'Broad terms indicating the plant structure involved in dispersal, distinguishing between taxonomic groups whose main dispersal units are spores, seeds, or fruit.', NULL, 'cat.', 'dispsarsal - spores, seeds, or fruit', '43', NULL, NULL),
('Seeds', 'fruiting_time', 'Months during which taxon produces fruit with mature seeds.', NULL, 'date', 'Fruiting time, by month', '44', NULL, NULL),
('Seeds', 'reproductive_maturity', 'The age of a plant when they are able to set seed, indicating it is reproductively mature.', 'a', 'num', 'Age of reproductive maturity', '45', '0.1', '1000.0'),
('Seeds', 'seed_viability', 'Proportion of mature seeds in a sample that are capable of germinating under suitable conditions.', '{count}/{count}', 'num', 'Seed viability percent', '46', '0.0', '1.0'),
('Seeds', 'serotiny', 'Categorical variable describing whether a fruit or cone remains closed in the plant canopy after maturation until an environmental cue, usually a fire, but possibly also drought or extreme heat, triggers it to release its seeds.', NULL, 'cat.', 'Serotiny - fruit opening cues', '47', NULL, NULL),
('Natural Growth', 'competitive_stratum', 'Categorical descriptions of a taxon''s relative stature in its community, used to assess competitive heirarchies within a community.', NULL, 'cat.', 'Competitive stratum', '48', NULL, NULL),
('Natural Growth', 'dispersal_syndrome', 'Plant dispersal syndromes are generally assigned to species based on suites of diaspore characteristics associated with specific mechanisms of dispersal. Trait values are mostly given as the formal dispersal syndromes ending in ''chory'', a suffix meaning ''a specified method of plant dispersal''.', NULL, 'cat.', 'Diaspore dispersal syndrome', '49', NULL, NULL),
('Natural Growth', 'dispersers', 'Dominant diaspore dispersal agents, including both biotic agents (specific taxa) or abiotic mechanisms responsible for dispersing seeds (or other dispersal units) away from the parent plant.', NULL, 'cat.', 'Diaspore dispersal agents', '50', NULL, NULL),
('Natural Growth', 'nitrogen_fixing', 'Binary variable describing whether a plant has the capacity for nitrogen fixatation, indicating it engages in symbioses with microorganisms (most commonly bacteria or cyanobacteria) that are capable of nitrogen fixation. Nitrogen fixation capacity is usually identified by nodules on the plant roots.', NULL, 'cat.', 'Plant nitrogen fixation capacity', '51', NULL, NULL),
('Natural Growth', 'resprouting_capacity_non_fire_disturbance', 'A plant''s ability to regenerate vegetatively (resprout) from a disturbance other than fire that causes 100% defoliation.', NULL, 'cat.', 'Plant vegetative response to disturbances other than fire', '52', NULL, NULL),
('Natural Growth', 'sprout_depth', 'Depth below the soil surface (positive number) or height above ground (negative number) from which buds (meristematic tissue) resprout following a disturbance, such as a fire.', NULL, 'num', 'Sprout depth', '53', '-100.0', '100.0'),
('Natural Growth', 'stem_growth_habit', 'Trait characterising a stem''s structure and 3-dimensional extent, including the position of stems, degree of branchiness, density of branches, and branch angles relative to other branches and the ground surface.', NULL, 'cat.', 'Stem growth habit', '54', NULL, NULL),
('Natural Growth', 'storage_organ', 'Plant structures  (tissues, organs, or other structures) where a plant stores excess carbohydrates (energy). The stored energy may be used for future growth, including clonal spread and regrowth following an annual unfavourable season, or for regrowth following a disturbance event (including post-fire regeneration or another disturbance event that causes leaf loss). Trait values include both generic terms and quite specific ones to accommodate the variation in detail provided across datasets.', NULL, 'cat.', 'carbohydrate storage organ', '55', NULL, NULL),
('Natural Growth', 'vegetative_reproduction_ability', 'A binary trait, indicating whether a plant taxon is able to reproduce and spread through the growth and division of vegetative material.', NULL, 'cat.', 'Vegetative reproduction ability', '56', NULL, NULL),
('Botany', 'bud_bank_location', 'The location of buds (meristematic tissue) on a plant that allows it to resprout following a fire, annual unfavourable season, or other disturbance event, such as a drought or cyclone. Trait values include both generic terms and quite specific ones to accommodate the variation in detail provided across datasets.', NULL, 'cat.', 'bud bank location - resprouting', '57', NULL, NULL),
('Botany', 'clonal_spread_mechanism', 'Mechanisms and structures (tissues, organs, or other structures) a plant uses to spread vegetatively, including the production of clones.', NULL, 'cat.', 'Clonal spread mechanism', '58', NULL, NULL),
('Botany', 'flower_structural_sex_type', 'Trait that captures floral sex, distinguishing among three states, bisexual, incompletely unisexual, and unisexual.', NULL, 'cat.', 'Floral structural sex', '59', NULL, NULL),
('Botany', 'genome_size', 'Mass of all chromosomes, the genome, in a somatic cell.', 'pg', 'num', 'Plant genome size', '60', '0.5', '100.0'),
('Botany', 'ploidy', 'Chromosome ploidy, the number of copies of each chromosome present in a somatic cell.', '{count}', 'num', 'Chromosome ploidy', '61', '1.0', '4.0'),
('Botany', 'root_system_type', 'Variable describing whether a plant has a tap root.', NULL, 'cat.', 'root system type - tap root', '62', NULL, NULL),
('Botany', 'sex_type', 'Plant sex type, indicating, for a taxon the type of flowers (male, female, and hermaphroditic) present on individual plants versus separate plants within a population.', NULL, 'cat.', 'Plant sex type', '63', NULL, NULL),
('Soil tolerances', 'plant_tolerance_calcicole', 'Classification scheme of plant soil calcium tolerance,  corresponding to its sensitivity to high soil pH. Plants are categorised as either calcifuge (intolerant of basic soils) or calcicole (tolerant of basic soils, such as calcareous sands and limestone derived soils).', NULL, 'cat.', 'Plant calcium sensitivity', '64', NULL, NULL),
('Soil tolerances', 'plant_tolerance_salt', 'Classification scheme of plant salt-tolerance categories, categorising taxa based on their tolerance of or sensitivity to salty soils, salt spray, or salt water.', NULL, 'cat.', 'Plant salt tolerance strategy', '65', NULL, NULL),
('Soil tolerances', 'plant_tolerance_soil_salinity', 'Maximum salinity tolerated by a taxon, reported as the conductivity of the soil.', NULL, 'num', 'Plant soil salinity tolerance', '66', '0.1', '100.0'),
('Soil tolerances', 'plant_type_by_resource_use', 'Classification scheme of plant resource requirements and tolerances, categorising taxa based on their water, soil nutrient, and soil salinity requirements and tolerances.', NULL, 'cat.', 'Plant resource requirements and tolerance', '67', NULL, NULL),
('Water response', 'plant_flood_regime_classification', 'Classification scheme of plant flood regime requirements and tolerances, categorising taxa into seven groups based on their germination and growth responses to flood regimes.', NULL, 'cat.', 'Plant flood regime response', '68', NULL, NULL),
('Water response', 'plant_tolerance_inundation', 'Categorical groupings, indicating the length of time a taxon is able to tolerate being under water.', NULL, 'cat.', 'Plant inundation tolerance', '69', NULL, NULL),
('Water response', 'plant_tolerance_water_logged_soils', 'Categorical groupings, indicating the length of time a taxon is able to tolerate water-logged soils.', NULL, 'cat.', 'Plant water-logging tolerance', '70', NULL, NULL);